let deStijlShader;

let textTexture;
let textString = "WOW";
let textBounds = { minX:0, maxX:1, minY:0, maxY:1 };

let customFont;

const MAX_SHADER_DEPTH = 16;

let params = {
    seed: 400,
    complexity: 5,
    minRectSize: 0.0,
    verticalSplitBias: 0.42,
    splitRangeMin: 0.26,
    splitRangeMax: 0.51,
    colorProbability: 0.0,
    greyProbability: 0.0,
    blackProbability: 0.0,
    redBias: 0.33,
    yellowBias: 0.33,
    blueBias: 0.34,
    lineColor: { r: 0, g: 0, b: 0 },
    palettePrimaryRed: { r: 219, g: 20, b: 59 },
    palettePrimaryYellow: { r: 255, g: 214, b: 0 },
    palettePrimaryBlue: { r: 0, g: 51, b: 153 },
    paletteWhite: { r: 242, g: 242, b: 242 },
    paletteGrey: { r: 179, g: 179, b: 179 },
    paletteBlack: { r: 13, g: 13, b: 13 }
};

function preload() {
  customFont = loadFont("https://openprocessing.org/sketch/2881718/files/ZNVT7.otf");
}

function generateTextTexture(){

    textTexture = createGraphics(1024,1024);
    textTexture.pixelDensity(1);
    textTexture.background(255);
    textTexture.fill(0);
    textTexture.textAlign(CENTER,CENTER);
    textTexture.textStyle(NORMAL);
	 textTexture.textFont(customFont);

    let size = 900;
    textTexture.textSize(size);

    while(textTexture.textWidth(textString) > 900){
        size -= 10;
        textTexture.textSize(size);
    }

    textTexture.text(textString,512,512);
    computeTextBounds();
}

function computeTextBounds(){

    textTexture.loadPixels();

    let minX=1024, maxX=0;
    let minY=1024, maxY=0;

    for(let y=0;y<1024;y++){
        for(let x=0;x<1024;x++){

            let i = 4*(y*1024+x);
            let r = textTexture.pixels[i];

            if(r < 250){
                if(x<minX) minX=x;
                if(x>maxX) maxX=x;
                if(y<minY) minY=y;
                if(y>maxY) maxY=y;
            }
        }
    }

    textBounds.minX = minX/1024;
    textBounds.maxX = maxX/1024;
    textBounds.minY = minY/1024;
    textBounds.maxY = maxY/1024;
}

function colorObjToArray(c){
    return [c.r/255,c.g/255,c.b/255];
}

const vertShader = `
precision highp float;
attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;
void main(){
    vTexCoord=aTexCoord;
    vec4 pos=vec4(aPosition,1.0);
    pos.xy=pos.xy*2.0-1.0;
    gl_Position=pos;
}
`;

const fragShader = `
precision highp float;

varying vec2 vTexCoord;

uniform float u_seed;
uniform float u_complexity;
uniform float u_minRectSize;
uniform float u_verticalSplitBias;
uniform float u_splitRangeMin;
uniform float u_splitRangeMax;

uniform float u_colorProbability;
uniform float u_greyProbability;
uniform float u_blackProbability;
uniform float u_redBias;
uniform float u_yellowBias;
uniform float u_blueBias;

uniform vec3 u_lineColor;

uniform vec3 u_palettePrimaryRed;
uniform vec3 u_palettePrimaryYellow;
uniform vec3 u_palettePrimaryBlue;
uniform vec3 u_paletteWhite;
uniform vec3 u_paletteGrey;
uniform vec3 u_paletteBlack;

uniform sampler2D u_textTexture;
uniform vec4 u_textBounds;

#define MAX_DEPTH ${MAX_SHADER_DEPTH}

float hash12(vec2 p){
    vec3 p3=fract(vec3(p.xyx)*0.1031);
    p3+=dot(p3,p3.yzx+33.33);
    return fract((p3.x+p3.y)*p3.z);
}

vec3 getColor(float r){
    float blackB=u_blackProbability;
    float greyB=blackB+u_greyProbability;
    float primaryB=greyB+u_colorProbability*(1.0-greyB);

    if(r<blackB) return u_paletteBlack;
    if(r<greyB) return u_paletteGrey;
    if(r<primaryB){
        float c=fract(r*123.45);
        if(c<u_redBias) return u_palettePrimaryRed;
        if(c<u_redBias+u_yellowBias) return u_palettePrimaryYellow;
        return u_palettePrimaryBlue;
    }
    return u_paletteWhite;
}

void main(){

    vec2 uv=vTexCoord;
    uv.y=1.0-uv.y;

    vec2 cPos=vec2(0.0);
    vec2 cSize=vec2(1.0);

    for(int i=0;i<MAX_DEPTH;i++){
        if(float(i)>=u_complexity) break;
        if(cSize.x<u_minRectSize||cSize.y<u_minRectSize) break;

        float r=hash12(cPos+float(i)+u_seed);
        bool vertical=r>(1.0-u_verticalSplitBias);
        float posRel=mix(u_splitRangeMin,u_splitRangeMax,fract(r*3.1));

        vec2 nPos=cPos;
        vec2 nSize=cSize;

        if(vertical){
            float split=cPos.x+cSize.x*posRel;
            if(uv.x<split){
                nSize.x=split-cPos.x;
            }else{
                nPos.x=split;
                nSize.x=cPos.x+cSize.x-split;
            }
        }else{
            float split=cPos.y+cSize.y*posRel;
            if(uv.y<split){
                nSize.y=split-cPos.y;
            }else{
                nPos.y=split;
                nSize.y=cPos.y+cSize.y-split;
            }
        }

        cPos=nPos;
        cSize=nSize;
    }

    float r=hash12(cPos+u_seed);
    vec3 fillColor=getColor(r);

    vec2 localUV=(uv-cPos)/cSize;

    // Remap only actual text bounding box
    vec2 textUV;
    textUV.x=mix(u_textBounds.x,u_textBounds.y,localUV.x);
    textUV.y=mix(u_textBounds.z,u_textBounds.w,localUV.y);

    vec3 textSample=texture2D(u_textTexture,textUV).rgb;
    float mask=smoothstep(0.4,0.6,1.0-textSample.r);

    vec3 finalColor=mix(fillColor,u_lineColor,mask);

    gl_FragColor=vec4(finalColor,1.0);
}
`;

function setup(){
    createCanvas(windowWidth,windowHeight,WEBGL);
    noStroke();

    generateTextTexture();

    deStijlShader=createShader(vertShader,fragShader);

    const gui=new lil.GUI({title:"Controls"});

    gui.add(params,'complexity',1,MAX_SHADER_DEPTH,1);
    gui.add(params,'minRectSize',0.0,0.1,0.001);
    gui.add(params,'verticalSplitBias',0.0,1.0,0.01);
    gui.add(params,'splitRangeMin',0.0,0.49,0.01);
    gui.add(params,'splitRangeMax',0.51,1.0,0.01);
    gui.add(params,'colorProbability',0.0,1.0,0.01);
    gui.add(params,'greyProbability',0.0,1.0,0.01);
    gui.add(params,'blackProbability',0.0,1.0,0.01);
    gui.add(params,'redBias',0.0,1.0,0.01);
    gui.add(params,'yellowBias',0.0,1.0,0.01);
    gui.add(params,'blueBias',0.0,1.0,0.01);
    gui.addColor(params,'lineColor');

    gui.add({text:textString},'text')
       .name("Tile Text")
       .onChange(v=>{
            textString=v;
            generateTextTexture();
       });

	gui.add(params, 'seed')
   .name('Seed')
   .step(0.01)
   .onChange(()=>generateTextTexture());

	gui.add({ save: () => {
        saveCanvas('output_' + floor(random(10000)), 'png');
    }}, 'save').name("Save PNG");
}

function draw(){

    shader(deStijlShader);

    deStijlShader.setUniform('u_seed',params.seed);
    deStijlShader.setUniform('u_complexity',params.complexity);
    deStijlShader.setUniform('u_minRectSize',params.minRectSize);
    deStijlShader.setUniform('u_verticalSplitBias',params.verticalSplitBias);
    deStijlShader.setUniform('u_splitRangeMin',params.splitRangeMin);
    deStijlShader.setUniform('u_splitRangeMax',params.splitRangeMax);
    deStijlShader.setUniform('u_colorProbability',params.colorProbability);
    deStijlShader.setUniform('u_greyProbability',params.greyProbability);
    deStijlShader.setUniform('u_blackProbability',params.blackProbability);
    deStijlShader.setUniform('u_redBias',params.redBias);
    deStijlShader.setUniform('u_yellowBias',params.yellowBias);
    deStijlShader.setUniform('u_blueBias',params.blueBias);
    deStijlShader.setUniform('u_lineColor',colorObjToArray(params.lineColor));
    deStijlShader.setUniform('u_palettePrimaryRed',colorObjToArray(params.palettePrimaryRed));
    deStijlShader.setUniform('u_palettePrimaryYellow',colorObjToArray(params.palettePrimaryYellow));
    deStijlShader.setUniform('u_palettePrimaryBlue',colorObjToArray(params.palettePrimaryBlue));
    deStijlShader.setUniform('u_paletteWhite',[242/255,242/255,242/255]);
    deStijlShader.setUniform('u_paletteGrey',[179/255,179/255,179/255]);
    deStijlShader.setUniform('u_paletteBlack',[13/255,13/255,13/255]);

    deStijlShader.setUniform('u_textTexture',textTexture);
    deStijlShader.setUniform('u_textBounds',[
        textBounds.minX,
        textBounds.maxX,
        textBounds.minY,
        textBounds.maxY
    ]);

    rect(-width/2,-height/2,width,height);
}

function windowResized(){
    resizeCanvas(windowWidth,windowHeight);
}

